const r = await api.get("/customers");
const list = Array.isArray(r) ? r : (r.items || r.customers || r.data || []);
console.log("top-level keys:", Array.isArray(r) ? "(array)" : Object.keys(r));
if (list.length) console.log("record keys:", Object.keys(list[0]));
console.log("count:", list.length);

const r = await api.get("/customers");
const list = r.items;
const best = list.reduce((a, b) => (b.points > a.points ? b : a));
const ties = list.filter(c => c.points === best.points).map(c => c.id);
console.log({ total_count: r.count, fetched: list.length, max_points: best.points, top_ids: ties });

